\label{def:class}
Let $\mathcal F$ be a family of bounded Borel functions on $[0,\infty)$.
An \emph{operator network with $\mathcal F$-layers} is a finite composition of maps acting on finitely many channels, each of which is
\begin{enumerate}[label=(\roman*)]
    \item a layer $\psi(L_0)$, $\psi\in\mathcal F$, applied to one channel;
    \item the pointwise product of two channels;
    \item a pointwise affine map of channels, whose coefficients may depend on the constants defining the coefficient class (such as $\bar a$ below).
\end{enumerate}
We consider two admissible families:
\begin{align*}
    \mathcal{F}_{\mathrm{heat}}&=\Bigl\{\textstyle\sum_{j\le J}a_j\mathrm{e}^{-t_j\lambda}\Bigr\}&&\text{(finite exponential sums)},\\
    \mathcal{F}_{\mathrm{mix}}&=\mathcal{F}_{\mathrm{heat}}\cup\Bigl\{\frac{s}{1+s\lambda}\Bigr\}&&\text{(one resolvent allowed)}.
\end{align*}

\label{lem:bookkeeping}
For $\mathcal O$ of the form \eqref{eq:conv-form},
\begin{equation}
    \label{eq:bookkeeping}
    \norm{\mathcal Ou}_1\le\Bigl(\sum_\mu\abs{\hat b_\mu}\sup_{k\ne0,\ k+\mu\ne0}m_\mu(k)\Bigr)\norm{u}_1,\qquad
    m_\mu(k):=\frac{\abs{k+\mu}\,\abs{c(k+\mu,\mu)}}{\abs{k}}.
\end{equation}
Moreover, for $k\ne0\ne k'=k+\mu$,
\begin{equation}
    \label{eq:F1}
    \frac{\abs{\mu}^2}{\abs{k'}\abs{k}}\le2\abs{\mu}.
\end{equation}

\label{lem:HR}
If $r$ satisfies \textup{(H$_R$)}{}, then for $\lambda\ge1$
\[
    \abs{r(\lambda)-\lambda^{-1}}\le\lambda^{-1}\bigl(\delta+2\cdot\mathbf{1}_{\lambda>\Lambda}\bigr),\qquad
    \abs{r(\lambda)}\le(1+\delta)\lambda^{-1},
\]
and for every $g\in L^2$
\begin{equation}
    \label{eq:HR-consequences}
    \norm{(R_m-R)g}_1\le(\delta+2\Lambda^{-1/2})\norm{g},\qquad\norm{R_mg}_1\le(1+\delta)\norm{g},
\end{equation}
with $\Lambda^{-1/2}:=0$ if $\Lambda=\infty$.

\label{lem:resolvent}
Let $s,T>0$.
The function $r(\lambda)=(1-\mathrm{e}^{-T\lambda})\,s/(1+s\lambda)$ satisfies $r(0)=0$ and \textup{(H$_R$)}{} with $\Lambda=\infty$ and $\delta=\mathrm{e}^{-T}+1/(1+s)$, provided this quantity is at most $1$.

\label{rem:bakry-emery}
Lemma~\ref{lem:product-defect} is the Fourier form on $\mathbb{T}^d$ of the semigroup interpolation identity $P_t(uv)-P_tu\,P_tv=2\int_0^tP_s\Gamma(P_{t-s}u,P_{t-s}v)\,\mathrm{d} s$ \cite{BGL14}, which is not new; its abstract form is Lemma~\ref{lem:interpolation}.
What is used below is the two-sided bound on $F_t$: the multiplier of $\Gamma_t-\Gamma$ is $(\mu\cdot k)(1-F_t)$, which is small for $t(\abs{k}^2+\abs{\mu}^2)\ll1$ and bounded by $\abs{\mu\cdot k}$ otherwise.

\label{thm:step}
Let $\theta\in(0,1]$, $b\in A^{1+\theta}$ real, $t,\tau>0$, $T\ge\frac12$, and let $R_m=r(L_0)$ where $r(0)=0$ and $r$ satisfies \textup{(H$_R$)}{} for some $\delta\in(0,1]$ and $\Lambda\in[1,\infty]$.
Define the block
\begin{equation}
    \label{eq:block}
    K^{\mathrm{net}} u:=(I-P_T)(bu)+R_m\bigl(\Gamma_t(b,u)-u\,b_\tau\bigr),\qquad b_\tau=(I-P_\tau)b/\tau.
\end{equation}
Then $K^{\mathrm{net}}\in\mathcal{L}(\dot H^1)$ has mean-zero output and
\begin{equation}
    \label{eq:Aprime}
    \begin{multlined}
    \norm{K^{\mathrm{net}}-K_b}_{\mathcal{L}(\dot H^1)}\le\norm{b}_{A^{1+\theta}}\Bigl[\mathrm{e}^{-T}+3\delta+12\Lambda^{-\theta/2}\\
    +(1+\delta)\bigl(4\sqrt t+(10t)^{\theta/2}\bigr)+2(1+\delta)(\tau/2)^{\theta/2}\Bigr],
    \end{multlined}
\end{equation}
with $\Lambda^{-\theta/2}:=0$ if $\Lambda=\infty$.
In particular, for every $B\ge1$ and $\eta_0\in(0,1]$ there are explicit $(t,\tau,T)$ and a choice of $r$ in either family such that $\norm{K^{\mathrm{net}}-K_b}_{\mathcal{L}(\dot H^1)}\le\eta_0$ whenever $\norm{b}_{A^{1+\theta}}\le B$:
\begin{enumerate}[label=(\alph*)]
    \item \emph{heat family} ($\mathcal{F}_{\mathrm{heat}}$): $r$ from Lemma~\ref{lem:sinc} with $\delta_0=\eta_0/(15B)$, $\Lambda=(60B/\eta_0)^{2/\theta}$, $T=\log(5/\delta_0)$, and
    \[
        t=\frac1{40}\Bigl(\frac{\eta_0}{20B}\Bigr)^{2/\theta},\qquad\tau=2\Bigl(\frac{\eta_0}{20B}\Bigr)^{2/\theta};
    \]
    the block uses $m+3=O(\theta^{-1}\log^2(B/\eta_0))$ heat applications (Definition~\ref{def:counting});
    \item \emph{mixed family} ($\mathcal{F}_{\mathrm{mix}}$): $r$ from Lemma~\ref{lem:resolvent} with $\delta_0=\eta_0/(15B)$, $T=\log(2/\delta_0)$, $s=2/\delta_0$, and the same $t,\tau$; the block uses $3$ heat applications and one resolvent application.
\end{enumerate}
In both cases the same $T$ is used in $r$ and in the factor $I-P_T$ of \eqref{eq:block}, and the parameters depend only on $(\theta,B,\eta_0)$, not on $b$; the coefficient enters only as an input channel.

\label{rem:schematic}
By linearity, $K^{\mathrm{net}} v=(I-P_T)\bigl[bv+S(\Gamma_t(b,v)-v\,b_\tau)\bigr]$ with $R_m=(I-P_T)S$, where $S=h\sum_j\mathrm{e}^{jh}P_{\mathrm{e}^{jh}}$ (heat family) or $S=sJ_s$ (mixed family).
After the precomputation of $b=a/\bar a-1$, $P_tb$, $b_\tau=(b-P_\tau b)/\tau$ and $v_0=(I-P_T)Sf$, block $i$ forms the products $w=bv_i$, $P_tb\cdot P_tv_i$ and $v_ib_\tau$, sets $g=\frac1{2t}[P_tw-P_tb\,P_tv_i]-v_ib_\tau$ and returns $v_{i+1}=v_0-(I-P_T)[w+Sg]$; all blocks share their parameters.

\label{def:counting}
One \emph{heat application} is one evaluation of one $P_t$, $t>0$, on one channel; one \emph{resolvent application} is one evaluation of $J_s$ on one channel.
By linearity, $(I-P_T)$ is applied once per block to the merged channel $bv+S(\Gamma_t(b,v)-v\,b_\tau)$ (Remark~\ref{rem:schematic}); the identity costs nothing; and the shared evaluations $P_tb$, $P_\tau b$ are counted once.

\label{rem:floating}
Coefficient magnitudes are polynomial in $B\kappa^2/(\varepsilon\bar a)$ with exponent $2/\theta$ (row (f)), and evaluating $\Gamma_t$ as $\frac1{2t}[P_t(bv)-P_tb\,P_tv]$ loses about $\log_{10}(1/(2t))$ digits through cancellation.
With the proved constants the construction is therefore realisable in double precision only for moderate $\varepsilon$; the threshold depends on the recipe, since
\begin{align*}
    \frac1{2t}&=8000\,\frac{B^2}{\eta_0^2}&&\text{(Wiener-class recipe of Theorem~\ref{thm:step} at $\theta=1$)},\\
    \frac1{2t}&=12.5\,\frac{B^2}{\eta_0^2}&&\text{(recipe of Theorem~\ref{thm:dirichlet-main})}.
\end{align*}
Section~\ref{sec:numerics} reports empirical thresholds for one example and both recipes, which are observations, not theorems.
The cancellation is intrinsic to synthesising a derivative from a semigroup at scale $\sqrt t\asymp\eta_0/B$; the resolvent removes the smallest exponential-sum times but not $1/(2t)$, and supplying $L_0a$ as an input channel removes the $\tau$-channel but not $\Gamma_t$.

\label{rem:saturation}
The rates $\sqrt t$ and $\Lambda^{-1/2}$ in \eqref{eq:Aprime} do not improve for $b\in A^\sigma$, $\sigma>2$, since they arise from high frequencies of $u$ (the regimes $\abs{k}\ge2\abs{\mu}$ in term (3) and $\abs{k}\ge\abs{k'}/2$ in term (4)), and the operator-norm bounds do not improve for data smoother than $L^2$; only the $\tau$-term improves, to $(1+\delta)\tau\norm{b}_{A^3}$ for $b\in A^3$.
In the $t$- and $\Lambda$-channels the construction therefore cannot trade coefficient regularity for resolution, unlike Galerkin-based emulations.

\label{ass:M}
$(X,\mathcal B,\mu)$ is a probability space with $\mu$-complete $\sigma$-algebra, and $\mathcal{E}$ is a symmetric, strongly local Dirichlet form on $L^2(X,\mu)$ with dense domain $V:=D(\mathcal{E})$, generating a Markov semigroup \cite[(2.1), p.~347; p.~348]{AGS15}.
Let $L_0\ge0$ be the self-adjoint operator defined by $\mathcal{E}(f,g)=\int(L_0f)g\,\mathrm{d}\mu$ for $f\in D(L_0)$, $g\in V$ (so $L_0=-\Delta_{\mathcal{E}}$ in the notation of \cite[p.~350]{AGS15}), and $P_t=\mathrm{e}^{-tL_0}$.
Moreover:
\begin{enumerate}[label=(\roman*)]
    \item $\mu$ is invariant, $\int P_tf\,\mathrm{d}\mu=\int f\,\mathrm{d}\mu$ for $f\in L^1(\mu)$ \cite[(2.12), p.~350]{AGS15}; hence $P_t1=1$;
    \item $\sigma(L_0)\subset\{0\}\cup[1,\infty)$ and $\ker L_0=\mathbb{R}\mathbf{1}$;
    \item $\mathcal{E}$ satisfies $\mathrm{BE}(-K,\infty)$ for some $K\ge0$ in the sense of \cite[Def.~2.4, p.~357]{AGS15} (in the notation of \cite{AGS15}, $\mathrm{BE}(K',\infty)$ with $K'=-K$).
\end{enumerate}

\label{thm:dirichlet-step}
Let Assumption~\ref{ass:M} hold, let $b\in L^\infty(\mu)\cap D(L_0)$ be real with $\norm{b}_{\mathcal B}<\infty$, let $t,\tau>0$, $T\ge\frac12$, and let $R_m=r(L_0)$ with $r(0)=0$ satisfying \textup{(H$_R$)}{} with $(\delta,\Lambda)$ (Definition~\ref{def:HR}; in particular $\delta\le1$).
Then $K^{\mathrm{net}}\in\mathcal{L}(\dot H^1)$ has mean-zero output and
\begin{multline*}
    \norm{K^{\mathrm{net}}-K_b}_{\mathcal{L}(\dot H^1)}\le\mathrm{e}^{-T}\norm{b}_\infty+(\delta+2\Lambda^{-1/2})\norm{b}_{\mathcal B}\\
    +(1+\delta)\bigl(1.37\,\mathrm{e}^{Kt}\sqrt t\,\norm{b}_{\mathcal B}+1.89\,\mathrm{e}^{K\tau}\sqrt\tau\,\norm{L_0b}_\infty\bigr).
\end{multline*}

\label{lem:spectral}
Let $c_0:=\sup_{x>0}(1-\mathrm{e}^{-x^2})/x\le0.6382$.
For $u\in V$, $g\in L^2$ and $r,s>0$:
